  const resultPath = referenceDir + '/.r-' + nonce;
  const answerPath = submissionDir + '/answer.mjs';
  let pinned = [
    'test("empty array", () => { assert.deepStrictEqual(dedupeSorted([]), []); });',
    'test("single element", () => { assert.deepStrictEqual(dedupeSorted([5]), [5]); });',
    'test("no duplicates", () => { assert.deepStrictEqual(dedupeSorted([1, 2, 3]), [1, 2, 3]); });',
    'test("all duplicates", () => { assert.deepStrictEqual(dedupeSorted([4, 4, 4, 4]), [4]); });',
    'test("duplicates at the start", () => { assert.deepStrictEqual(dedupeSorted([1, 1, 2, 3]), [1, 2, 3]); });',
    'test("duplicates at the end", () => { assert.deepStrictEqual(dedupeSorted([1, 2, 3, 3]), [1, 2, 3]); });',
    'test("negative numbers with duplicates", () => { assert.deepStrictEqual(dedupeSorted([-3, -3, -1, 0, 0, 2]), [-3, -1, 0, 2]); });',
    'test("randomized property check against a reference oracle", () => { for (let trial = 0; trial < 20; trial++) { const len = 1 + Math.floor(Math.random() * 10); const arr = Array.from({ length: len }, () => Math.floor(Math.random() * 5) - 2).sort((a, b) => a - b); const expected = [...new Set(arr)]; assert.deepStrictEqual(dedupeSorted(arr), expected); } });'
  ].join('\n');
  try {
    const fromFile = fs.readFileSync(referenceDir + '/pinned-test-cases.txt', 'utf8');
    if (fromFile && fromFile.includes('test(')) pinned = fromFile;
  } catch {}
  const runnerSrc = [
    'import fs from "node:fs";',
    'import assert from "node:assert/strict";',
    'import { pathToFileURL } from "node:url";',
    'const resultPath = ' + JSON.stringify(resultPath) + ';',
    'const nonce = ' + JSON.stringify(nonce) + ';',
    'const answerPath = ' + JSON.stringify(answerPath) + ';',
    'const pinned = ' + JSON.stringify(pinned) + ';',
    'function report(ok, reason) { fs.writeFileSync(resultPath, JSON.stringify({ nonce: nonce, ok: ok, reason: String(reason) })); }',
    'const tests = [];',
    'function test(name, fn) { tests.push({ name: name, fn: fn }); }',
    'try {',
    '  const mod = await import(pathToFileURL(answerPath).href);',
    '  const dedupeSorted = mod.dedupeSorted;',
    '  if (typeof dedupeSorted !== "function") { report(false, "dedupeSorted missing"); process.exit(0); }',
    '  eval(pinned);',
    '  if (tests.length < 8) { report(false, "expected >= 8 tests, got " + tests.length); process.exit(0); }',
    '  let n = 0;',
    '  for (const t of tests) { await t.fn(); n++; }',
    '  if (n !== tests.length) { report(false, "incomplete"); process.exit(0); }',
    '  report(true, "all " + n + " tests passed");',
    '} catch (e) {',
    '  try { report(false, (e && e.message) ? e.message : String(e)); } catch (e2) {}',
    '}'
  ].join('\n');
